typedef int (*validator_fn)(const struct request *);
static validator_fn const validators[] = { check_size, check_encoding, check_fields };

int ingress_validate(const struct request *r) {
    for (size_t i = 0; i < sizeof validators / sizeof *validators; ++i)
        if (validators[i](r) != 0)
            return -1;            /* reject before dispatch */
    return 0;
}
